class 저금통:
    def __init__(self):
        self.돈 = 0
    def 넣기(self, 얼마):
        self.돈 += 얼마
    def 꺼내기(self, 얼마):
        if 얼마 > self.돈:
            print("모자라요")
        else:
            self.돈 -= 얼마

통 = 저금통()
통.넣기(1000)
통.넣기(500)
통.꺼내기(700)
통.꺼내기(2000)
print(통.돈)

