challenge.solution:
class 학생:
    def __init__(self, 이름):
        self.이름 = 이름
        self.점수들 = []
    def 더하기(self, 점수):
        self.점수들.append(점수)
    def 평균(self):
        return sum(self.점수들) / len(self.점수들)

가 = 학생("민수")
가.더하기(90)
가.더하기(80)
가.더하기(70)
print(가.이름, 가.평균())
